function comp(a){let s=0;Object.keys(WT).forEach(k=>{if(((a.s[k]||"").trim()).length>=20)s+=WT[k]});if(a.links.length||a.srcs.length)s+=10;return s}
function clar(a){const txt=(a.s.sym+". "+a.s.cause+". "+a.s.res.replace(/\n/g,". ")+". "+a.s.notes).replace(/\d\.\s/g,"");const sn=txt.split(/[.!?]+\s/).filter(x=>x.trim().length>2);if(!sn.length)return 0;const w=sn.reduce((n,x)=>n+x.trim().split(/\s+/).length,0)/sn.length;const steps=(a.s.res.match(/^\d+\./gm)||[]).length;return Math.round(clamp(100-6*Math.max(0,w-10)+(steps>=3?4:0),0,100))}
const cite=a=>Math.min(100,30*(a.srcs.length+Math.min(a.links.length,2)));
const fresh=a=>{if(a.exp&&a.exp<NOW)return 0;const g=age(a);return Math.round(clamp(100*(365-g)/(365-90),0,100))}
const qual=a=>({c:comp(a),l:clar(a),r:cite(a),f:fresh(a),q:Math.round(.35*comp(a)+.25*clar(a)+.15*cite(a)+.25*fresh(a))});
