function gate(a,to){const from=a.st,r=roleIdx(),q=comp(a);const no=m=>({ok:false,msg:m}),yes={ok:true,msg:""};
 if(to===from)return no("Already there.");
 if(from==="Retired")return no("Retired articles are read-only. Create a new article instead.");
 if(r<1&&to!=="Draft")return no("Candidates can only create drafts. A Contributor needs to structure this article.");
 if(from==="Draft"&&to==="In review"){if(q<70)return no("Structure gate: needs at least 70% completeness, now "+q+"%. Fill the missing sections first.");if(!a.rvw)return no("Name a reviewer before submitting.");return yes}
 if(from==="Draft")return no("A draft cannot skip review. Move it to Structure first.");
 if(to==="Published"){if(!canPub())return no("Publishing needs the Publisher role. You are acting as "+K.role+".");if(from==="In review"&&!a.appr)return no("Publish gate: reviewer "+a.rvw+" has not approved yet.");if(from==="Retiring"&&!a.appr)return no("Re-publishing a flagged article needs a fresh reviewer approval.");return yes}
 if(from==="In review"&&(to==="Draft"||to==="Retiring"))return r>=1?yes:no("Needs Contributor.");
 if(from==="Published"&&to==="Retiring")return yes;
 if(from==="Published"&&(to==="In review"||to==="Draft"))return canPub()?yes:no("Pulling a published article back needs the Publisher role.");
 if(from==="Retiring"&&(to==="In review"||to==="Draft"))return yes;
 if(to==="Retired")return canAppr()?yes:no("Retiring needs Publisher or Coach.");
 return no("That move is not allowed by the lifecycle.")}
function gateChip(a){const q=comp(a);
 if(a.st==="Draft")return q>=70?`<span class="pill good" title="Structure gate: at least 70% complete and a reviewer named">Structure gate ok · ${q}%</span>`:`<span class="pill warn" title="Structure gate: at least 70% complete and a reviewer named">Gate: ${q}% of 70% complete</span>`;
 if(a.st==="In review")return a.appr?`<span class="pill good" title="Publish gate">${ico("lock")} ${esc(a.rvw)} approved</span>`:`<span class="pill warn" title="Publish gate: reviewer approval and Publisher role">${ico("lock")} Needs ${esc(a.rvw||"a reviewer")}</span>`;
 if(a.st==="Published")return isStale(a)?`<span class="pill bad">Stale: review due</span>`:`<span class="pill mute">Review by ${fD(addD(a.rev,365))}</span>`;
 if(a.st==="Retiring")return `<span class="pill warn" title="Retire needs Publisher or Coach">${ico("lock")} Retire: Publisher</span>`;
 return `<span class="pill mute">Archived</span>`}
function move(id,to,via){const a=byId(id);if(!a)return false;const g=gate(a,to);if(!g.ok){toast(g.msg,"bad");audit("blocked move",a.id+" "+a.st+" → "+to+" · "+g.msg);return false}
 const from=a.st;a.st=to;if(to==="Published"){a.rev=NOW;if(!a.exp||a.exp<NOW)a.exp=addD(NOW,365);a.conf="Validated";a.ver.push({v:"v"+(a.ver.length+1),d:NOW,by:a.own,note:"Published",t:a.t,s:Object.assign({},a.s)})}
 if(to==="In review"){a.appr=false;a.conf="Not validated"}if(to==="Draft")a.appr=false;
 recalc();audit("moved article "+(via||""),a.id+" "+from+" → "+to);toast(a.id+" moved to "+(LANE_OF[to]||to)+" ("+to+")","good");return true}

/* ---------- article drawer ---------- */
function openArt(id){const a=byId(id);if(!a)return;K.sel=id;const q=qual(a),age_=age(a),st=isStale(a);
 const nexts=STATES.filter(s=>s!==a.st&&s!=="Retired").map(s=>`<button class="chip" data-kcs-mv="${a.id}:${s}" title="${esc(gate(a,s).msg||"Allowed for your role")}">${esc(s)}${gate(a,s).ok?"":" (locked)"}</button>`).join("");
 openDrawer(`<div class="row">${stPill(a.st)}${pill(a.type,"info")}<span class="muted small">${a.id} · ${esc(a.conf)}</span></div>
 <h2 style="font-size:28px;margin:10px 0 6px;padding-right:60px">${esc(a.t)}</h2>
 <p class="story" data-role="story" style="font-size:16px">${st?`<b>Needs a review.</b> Last reviewed ${age_} days ago${a.exp<NOW?" and past its expiry on "+fD(a.exp):""}. ${esc(a.own)} owns it.`:`Owned by ${esc(a.own)}, reviewed ${fD(a.rev)} by ${esc(a.rvw||"nobody yet")}. Reused ${a.reuse} times.`}</p>
 <div class="kcs-qrow"><div class="kcs-qnum num" data-role="metric">${q.q}</div><div class="kcs-qparts">${[["Completeness",q.c],["Clarity",q.l],["Citations",q.r],["Freshness",q.f]].map(x=>`<div><span>${x[0]}</span>${qBar(x[1],90)}<b data-role="metric">${x[1]}</b></div>`).join("")}</div></div>
 <div class="formula" style="font-size:14px;margin:8px 0">0.35×${q.c} + 0.25×${q.l} + 0.15×${q.r} + 0.25×${q.f} = ${q.q}</div>
 <dl class="kv"><dt>Audience</dt><dd>${a.aud.map(x=>pill(x,"mute")).join(" ")}</dd><dt>Classification</dt><dd>${pill(a.cls,a.cls==="Restricted"?"bad":a.cls==="Confidential"?"warn":"info")}</dd><dt>Service</dt><dd>${esc(a.svc)}</dd><dt>Reviewed</dt><dd>${fD(a.rev)} <span class="muted">(${age_} days)</span></dd><dt>Expires</dt><dd>${fD(a.exp)}</dd><dt>Usage</dt><dd data-role="metric">${a.views} views · ${a.defl} deflections · ${a.reuse} reuses · ${a.help||"no"}% helpful</dd></dl>
 ${SECS.filter(s=>a.s[s[0]]).map(s=>`<div class="eyebrow" style="margin:12px 0 4px">${s[1]}</div><div class="kcs-sec">${esc(a.s[s[0]])}</div>`).join("")}
 <div class="eyebrow" style="margin:12px 0 6px">Sources and related records</div><div class="row">${a.srcs.map(s=>`<span class="chip">${esc(s)}</span>`).join("")}${a.links.map(linkChip).join("")}${a.srcs.length+a.links.length?"":'<span class="muted small">None yet. Citations score 0.</span>'}</div>
 <div class="eyebrow" style="margin:14px 0 6px">Move to (gates apply to ${esc(K.role)})</div><div class="row">${nexts}</div>
 <div class="row" style="margin-top:16px"><button class="btn primary" data-kcs-edit="${a.id}">Open in editor</button>${a.st==="In review"&&canAppr()&&!a.appr?`<button class="btn" data-kcs-approve="${a.id}">Approve as ${esc(K.role)}</button>`:""}${a.st==="Retiring"&&canAppr()?`<button class="btn danger" data-kcs-retire="${a.id}">Retire article</button>`:""}${st?`<button class="btn" data-kcs-nudge="${a.id}">Nudge ${esc(a.own)}</button>`:""}</div>`);audit("opened article",a.id)}

/* ---------- library ---------- */
function libRows(){const q=K.q.toLowerCase();return ART.filter(a=>(!K.ft||a.type===K.ft)&&(!K.fs||(K.fs==="stale"?isStale(a):a.st===K.fs))&&(!K.fa||a.aud.includes(K.fa))&&(!q||(a.t+" "+a.id+" "+a.svc+" "+a.topic+" "+a.own+" "+Object.values(a.s).join(" ")).toLowerCase().includes(q)))}
function libTable(){const rows=libRows();if(!rows.length)return empty("No articles match","Clear a filter or search for a different word.");
 return `<div class="tablewrap"><table><thead><tr><th>Article</th><th>Type</th><th>State</th><th>Audience</th><th>Reviewed</th><th>Quality</th><th>Views</th><th>Owner</th></tr></thead><tbody>${rows.map(a=>{const q=qual(a).q;return `<tr data-kcs-open="${a.id}" tabindex="0"><td><b>${esc(a.t)}</b><span class="sub">${a.id} · ${esc(a.svc)}</span></td><td>${a.type}</td><td>${stPill(a.st)}</td><td>${esc(a.aud.slice(0,2).join(", "))}${a.aud.length>2?" +"+(a.aud.length-2):""}</td><td>${fD(a.rev)}${isStale(a)?` ${pill("stale","bad")}`:""}</td><td><span class="row" style="gap:8px;flex-wrap:nowrap">${qBar(q,56)}<b class="num" data-role="metric">${q}</b></span></td><td class="num" data-role="metric">${a.views}</td><td>${esc(a.own)}</td></tr>`}).join("")}</tbody></table></div><div class="muted small" data-role="story" style="margin-top:6px">${rows.length} of ${ART.length} articles shown. Click a row for details.</div>`}
const sel=(k,label,opts,val)=>`<label class="kcs-f"><span class="eyebrow">${label}</span><select class="fin" data-kcs-f="${k}"><option value="">All</option>${opts.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${esc(a[0])}" ${val===a[0]?"selected":""}>${esc(a[1])}</option>`}).join("")}</select></label>`;
function libPane(){return `<div class="kcs-bar"><label class="kcs-f kcs-grow"><span class="eyebrow">Search articles</span><input class="fin" type="search" data-kcs-q placeholder="Try: failover, retention, MFA" value="${esc(K.q)}" aria-label="Search articles"></label>${sel("ft","Type",TYPES,K.ft)}${sel("fs","State",[...STATES.map(s=>[s,s]),["stale","Stale (needs review)"]],K.fs)}${sel("fa","Audience",AUD,K.fa)}</div><div id="kcs-lib">${libTable()}</div>`}

/* ---------- kanban ---------- */
function kanPane(){const cards=a=>`<div class="kcs-kc" data-dnd-id="${a.id}" tabindex="0" data-kcs-open="${a.id}">${grip}<div class="kcs-kcb"><b>${esc(a.t)}</b><span class="muted small">${a.id} · ${a.type} · ${esc(a.own)}</span><div class="row" style="gap:6px">${gateChip(a)}<span class="pill metric" data-role="metric" title="Quality score">Q ${qual(a).q}</span></div></div></div>`;
 return `<div class="kcs-roles card glass"><div class="row sp"><div><b>Acting as</b> <span class="muted small">Gates change with the KCS role. Try dragging a card you are not allowed to move.</span></div><div class="row">${ROLES.map(r=>`<button class="chip" data-kcs-role="${r[0]}" aria-pressed="${K.role===r[0]}" title="${esc(r[1])}">${r[0]}</button>`).join("")}</div></div></div>
 <div class="kcs-lanes">${LANES.map(l=>{const L=ART.filter(a=>a.st===l[1]);return `<section class="kcs-lane glass"><header><div class="row sp"><h4>${l[0]}</h4>${stPill(l[1])}</div><span class="muted small">${l[2]}</span><span class="small"><b data-role="metric">${L.length}</b> ${L.length===1?"article":"articles"}</span></header><div class="kcs-cards" data-dnd="${l[1]}" data-dnd-scope="kcs_kan">${L.map(cards).join("")}</div></section>`}).join("")}</div>
 <div class="kcs-gates card glass"><h3 style="font-size:18px">Role gates on each move</h3><ul class="steps small"><li><b>Capture to Structure:</b> Contributor, at least 70% complete, reviewer named.</li><li><b>Structure to Reuse (publish):</b> Publisher role and an approval from the named reviewer. Shown as the lock chip.</li><li><b>Reuse to Improve:</b> any Contributor can flag an article that is wrong or stale.</li><li><b>Improve to Retired:</b> Publisher or Coach, from the article panel. ${ART.filter(a=>a.st==="Retired").length} article is already retired.</li></ul></div>`}

/* ---------- freshness ---------- */
function freshPane(){const p=pub(),st=p.filter(isStale).sort((a,b)=>age(b)-age(a));const bk=[["0 to 90",0,90],["91 to 180",91,180],["181 to 270",181,270],["271 to 365",271,365],["Over 365 or expired",366,9999]];
 const cnt=bk.map(b=>p.filter(a=>{const g=a.exp&&a.exp<NOW?9999:age(a);return g>=b[1]&&g<=b[2]}).length),mx=Math.max(...cnt,1);
 const m=METRICS.m_kbfresh;
 return `<div class="grid g2"><section class="card glass"><div class="cardhead"><div><h3>Freshness</h3><span class="muted small" data-role="story">${p.length-st.length} of ${p.length} published articles are inside their review window.</span></div>${fchip("m_kbfresh")}</div>
 <div class="row" style="align-items:flex-end;gap:18px"><span class="num" data-role="metric" style="font-size:54px;line-height:1">${m.cur}%</span><span class="muted small">target at least ${m.tgt}%</span></div>
 <div class="formula" style="margin:12px 0">${esc(m.f)}</div><div class="kcs-hist" role="img" aria-label="Published articles by days since last review">${bk.map((b,i)=>`<div><b class="num" data-role="metric">${cnt[i]}</b><i style="height:${Math.max(4,cnt[i]/mx*90)}px;background:var(--${i>=4?"bad":i===3?"warn":"good"}-f)"></i><span>${b[0]}</span></div>`).join("")}</div>
 <p class="muted small" style="margin-top:10px">Per-article freshness score: 100 when reviewed in the last 90 days, falling in a straight line to 0 at 365 days, and 0 once the expiry date has passed. This feeds the quality score at 25%.</p></section>
 <section class="card glass"><div class="cardhead"><div><h3>If freshness slips</h3><span class="muted small">Remediation attached to the metric.</span></div></div>
 <div class="rem"><div class="ico">${ico("bolt")}</div><div><b>${esc(m.rem.agent)} runs ${m.rem.ref}: ${esc(m.rem.title)}</b><div class="muted">${esc(m.rem.prog)}. Owners decide; the agent never publishes.</div></div></div>
 <div class="row" style="margin-top:14px"><button class="btn primary" data-kcs-nudgeall>Nudge all ${st.length} owners</button><button class="btn" data-go="kcs_gap">See knowledge gaps</button></div>
 <p class="story small" data-role="story" style="margin-top:12px">${st.length?`The oldest is <b>${esc(st[0].t)}</b>, ${age(st[0])} days since review. Its owner ${esc(st[0].own)} ${st[0].nudged?"was nudged "+st[0].nudged+" time"+(st[0].nudged>1?"s":""):"has not been nudged yet"}.`:"Nothing is stale."}</p></section></div>
 ${card("Stale articles",`Published articles past 12 months since review or past expiry, oldest first.`,st.length?`<div class="tablewrap"><table><thead><tr><th>Article</th><th>Days since review</th><th>Expiry</th><th>Owner</th><th>Used last 90 days</th><th></th></tr></thead><tbody>${st.map(a=>`<tr><td data-kcs-open="${a.id}"><b>${esc(a.t)}</b><span class="sub">${a.id} · ${esc(a.svc)}</span></td><td data-role="metric"><b class="num">${age(a)}</b></td><td>${fD(a.exp)} ${a.exp<NOW?pill("expired","bad"):""}</td><td>${esc(a.own)}</td><td data-role="metric">${a.reuse} reuses</td><td><div class="row" style="flex-wrap:nowrap"><button class="btn" data-kcs-nudge="${a.id}">${a.nudged?"Nudged "+a.nudged+"x":"Nudge owner"}</button><button class="btn quiet" data-kcs-edit="${a.id}">Refresh</button></div></td></tr>`).join("")}</tbody></table></div>`:empty("All fresh","No published article is past its review window."))}`}

/* ---------- quality and usage ---------- */
function bars(items,o){o=o||{};const mx=Math.max(...items.map(i=>i.v),1);return `<div class="kcs-bars">${items.map(i=>`<div class="kcs-br"><span class="kcs-bl" title="${esc(i.l)}">${esc(i.l)}</span><span class="kcs-bt"><i style="width:${Math.max(2,i.v/mx*100)}%;background:var(${i.c||o.c||"--accent"})"></i></span><b class="num" data-role="metric">${o.fmt?o.fmt(i.v):i.v}</b></div>`).join("")}</div>`}
function qualPane(){const L=live().filter(a=>a.st!=="Draft").map(a=>({a,q:qual(a)})).sort((x,y)=>x.q.q-y.q.q);const lo=L[0];
 const tv=ART.reduce((n,a)=>n+a.views,0),td=ART.reduce((n,a)=>n+a.defl,0),tr=ART.reduce((n,a)=>n+a.reuse,0),hv=pub().filter(a=>a.help);const hp=Math.round(hv.reduce((n,a)=>n+a.help,0)/Math.max(1,hv.length));
 const top=ART.slice().sort((a,b)=>b.reuse-a.reuse).slice(0,7).map(a=>({l:a.t,v:a.reuse,c:"--accent"}));const topd=ART.slice().sort((a,b)=>b.defl-a.defl).slice(0,5).map(a=>({l:a.t,v:a.defl,c:"--good-f"}));
 return `${tiles([TL("Views",tv.toLocaleString(),"all articles, last 90 days","info"),TL("Deflections",td.toLocaleString(),METRICS.m_deflect_kb.cur+"% of support searches","good"),TL("Reuse count",tr,"links to incidents and tickets","info"),TL("Helpful votes",hp+"%","average of published articles",hp>=75?"good":"warn")])}
 <div class="grid g2"><section class="card glass"><div class="cardhead"><div><h3>Article quality score</h3><span class="muted small" data-role="story">Average ${METRICS.m_kbq.cur} across ${live().length} live articles. Lowest: <b>${esc(lo.a.t)}</b> at ${lo.q.q}.</span></div>${fchip("m_kbq")}</div>
 <div class="formula" style="margin-bottom:10px">Quality = 0.35 × Completeness + 0.25 × Clarity + 0.15 × Citations + 0.25 × Freshness</div>
 <dl class="kv"><dt>Completeness</dt><dd>Points for each filled section: symptom 20, applies to 10, cause 20, resolution 35, notes 5, plus 10 for any related record or source.</dd><dt>Clarity</dt><dd>100 minus 6 for every word that the average sentence runs over 10, plus 4 when the resolution has three or more numbered steps.</dd><dt>Citations</dt><dd>30 points for each source or related record (up to two records), capped at 100.</dd><dt>Freshness</dt><dd>See the Freshness tab.</dd></dl>
 <div class="muted small">Worked example: ${esc(lo.a.id)} scores 0.35×${lo.q.c} + 0.25×${lo.q.l} + 0.15×${lo.q.r} + 0.25×${lo.q.f} = <b>${lo.q.q}</b>. Fix the lowest part first: ${lo.q.c<=Math.min(lo.q.l,lo.q.r,lo.q.f)?"fill the missing sections":lo.q.f<=Math.min(lo.q.l,lo.q.r)?"review the article":lo.q.r<=lo.q.l?"add sources":"shorten the sentences"}.</div></section>
 <section class="card glass"><div class="cardhead"><div><h3>Usage</h3><span class="muted small">Most reused and most deflecting articles.</span></div></div><div class="eyebrow">Reuse count (linked to a record)</div>${bars(top)}<div class="eyebrow" style="margin-top:12px">Deflections (resolved without a ticket)</div>${bars(topd)}
 <p class="muted small" style="margin-top:10px">Deflection counts a search that ends on the article with no ticket from that person in 24 hours. Reuse counts every time the article is linked to an incident or request.</p></section></div>
 ${card("Score by article","Lowest first. Click a row to open it.",`<div class="tablewrap"><table><thead><tr><th>Article</th><th>Quality</th><th>Completeness</th><th>Clarity</th><th>Citations</th><th>Freshness</th></tr></thead><tbody>${L.map(x=>`<tr data-kcs-open="${x.a.id}" tabindex="0"><td><b>${esc(x.a.t)}</b><span class="sub">${x.a.id} · ${x.a.st}</span></td><td><b class="num" data-role="metric">${x.q.q}</b></td>${[x.q.c,x.q.l,x.q.r,x.q.f].map(v=>`<td>${qBar(v,70)} <span class="small" data-role="metric">${v}</span></td>`).join("")}</tr>`).join("")}</tbody></table></div>`)}`}

/* ---------- home screen ---------- */
REG("kcs_home","Knowledge management","know","M5 4h11a3 3 0 0 1 3 3v13H8a3 3 0 0 1-3-3zM5 17a3 3 0 0 1 3-3h11M9 8h6",()=>{recalc();const p=pub(),st=p.filter(isStale),rv=ART.filter(a=>a.st==="In review"),k421=byId("KB0421");
 return `<div class="screen kfast">${hero("Knowledge management · KCS v6","Answers people can trust",`<b>${p.length} articles are published</b> and <b>${st.length} are stale</b>, including the portal failover runbook, last reviewed ${Math.round(age(k421)/30)} months ago. Its refresh draft is waiting on Tom Becker's review. Self-service now resolves <b>${METRICS.m_deflect_kb.cur}%</b> of support searches.`,`<div class="row">${fchip("m_kbfresh")}${fchip("m_deflect_kb")}${fchip("m_kbq")}<button class="btn primary" data-kcs-new>New article</button><button class="btn" data-go="kcs_ask">Ask the knowledge base</button>${whyPop("Knowledge is the first place an AI answer comes from, so its freshness and quality are shown next to the AI quality screens.")}</div>`)}${lensNote()}
 ${tiles([TL("Published",p.length,ART.filter(a=>a.st==="Draft").length+" drafts in progress","info"),TL("Stale",st.length,"oldest "+(st[0]?age(st[0]):0)+" days",st.length>2?"bad":"warn"),TL("Waiting on review",rv.length,rv.filter(a=>!a.appr).length+" need a reviewer decision",rv.length?"warn":"good"),TL("Quality score",METRICS.m_kbq.cur,"target "+METRICS.m_kbq.tgt,METRICS.m_kbq.cur>=METRICS.m_kbq.tgt?"good":"warn")])}
 ${views("kcs_hv",["Library","KCS lifecycle","Freshness","Quality and usage"],[libPane(),kanPane(),freshPane(),qualPane()])}</div>`});
DND.on("kcs_kan",(id,from,to)=>{if(from!==to)move(id,to,"by drag");render()});

