const pendingAI=()=>Object.keys(K.ed.ai).filter(k=>K.ed.ai[k]);
function checklist(){const e=K.ed,c=comp(edTmp());return [["Completeness at least 70%",c>=70,c+"% now"],["Resolution has numbered steps",(e.s.res.match(/^\d+\./gm)||[]).length>=2,"two or more steps"],["Reviewer named",!!e.rvw,e.rvw||"missing"],["At least one source or related record",e.links.length+e.srcs.length>0,(e.links.length+e.srcs.length)+" attached"],["AI-drafted sections reviewed by a human",pendingAI().length===0,pendingAI().length?pendingAI().length+" unreviewed":"all reviewed"],["Audience and classification labeled",e.aud.length>0&&!!e.cls,e.aud.join(", ")+" · "+e.cls]]}
