PR.forEach(p=>{p.appr={got:[]};});
const pOf=id=>PR.find(p=>p.id===id);
const cur=()=>pOf(K.pSel)||PR[0];
const vOf=(p,v)=>p.vers.find(x=>x.v===v);
const need=p=>["Prompt owner","AI governance lead"].concat(p.risk==="High"?["Security lead","Legal reviewer"]:[]).slice(0,p.risk==="Low"?1:p.risk==="Medium"?2:4);
const detect=t=>[...new Set([...(t||"").matchAll(/\{\{(\w+)\}\}/g)].map(m=>m[1]))];
const comp2=s=>s?+(.5*s.pass+.3*s.ground+.2*s.safe).toFixed(1):null;
const stP=s=>pill(s,{Production:"good","In approval":"info",Draft:"mute",Retired:"mute"}[s]);
const rkP=r=>pill(r+" risk",r==="High"?"bad":r==="Medium"?"warn":"good");
function pLoad(id){const p=pOf(id)||PR[0];K.pSel=p.id;const v=vOf(p,p.candV||p.prodV)||p.vers[p.vers.length-1];K.ped={id:p.id,name:p.name,purpose:p.purpose,owner:p.owner,model:p.model,risk:p.risk,text:v.text,note:"",usedBy:p.usedBy.slice(),base:v.v};K.ptest={vals:Object.assign({},p.vars),out:null,run:0};K.pvd=[Math.max(0,p.vers.length-2),p.vers.length-1]}
const fillT=(t,vals)=>t.replace(/\{\{(\w+)\}\}/g,(m,k)=>vals[k]!=null&&vals[k]!==""?vals[k]:"⟨"+k+" missing⟩");
function pVarsHTML(){const e=K.ped,vs=detect(e.text),p=pOf(e.id);return `<div class="eyebrow" style="margin-bottom:6px">Variables found in the prompt (${vs.length})</div><div class="row" style="gap:6px;margin-bottom:10px">${vs.map(v=>`<span class="pill metric">{{${v}}}</span>`).join("")||'<span class="muted small">None. Add {{name}} where a value goes.</span>'}</div>${vs.map(v=>`<label class="fld" style="margin-bottom:8px"><span class="flab">${v}</span><textarea class="fin" rows="2" data-kcs-pv="${v}">${esc(K.ptest.vals[v]!=null?K.ptest.vals[v]:"")}</textarea></label>`).join("")}`}
function pOutHTML(){const t=K.ptest,e=K.ped,p=pOf(e.id);if(!t.out)return `<p class="muted small">Press Run test to send the filled prompt to ${esc(e.model)} in the sandbox. The output here is scripted for the prototype, but the checks are real.</p>`;
 if(t.out.run){const s=t.out;return `<ul class="steps">${s.steps.map((x,i)=>`<li style="opacity:${i<=s.i?1:.35}">${x}${i<s.i||s.done?" "+pill("ok","good"):i===s.i?" "+pill("running","info"):""}</li>`).join("")}</ul>${s.done?`<div class="kcs-quote">${esc(s.text)}</div><div class="row small"><span class="pill mute" data-role="metric">${s.tin} tokens in</span><span class="pill mute" data-role="metric">${s.tout} out</span><span class="pill mute" data-role="metric">${s.ms} ms</span><span class="pill mute" data-role="metric">$${s.cost}</span><span class="pill ${s.missing?"bad":"good"}">${s.missing?s.missing+" variable missing":"all variables filled"}</span>${aiChip({model:e.model,conf:.9,title:"Prompt test output",note:"Sandbox run. Scripted for the prototype.",src:["Prompt "+e.id+" "+e.base],guards:["Sandbox data only","Output is not saved to records"]})}</div>`:""}`}return ""}
function pEditor(){const e=K.ped,p=pOf(e.id),models=["Claude Sonnet","Claude Haiku","GPT (council)","Gemini"];
 return `<div class="grid g2" style="align-items:start"><section class="card glass"><div class="cardhead"><div><h3>${p?"Edit "+esc(p.name):"New prompt"}</h3><span class="muted small" data-role="story">${p?`Saving creates version ${"v"+(p.vers.length+1)} as a candidate. Production keeps ${p.prodV||"nothing"} until the approval workflow finishes.`:"A new prompt starts as a Draft with no production version."}</span></div></div>
 <div class="fgrid"><label class="fld wide"><span class="flab">Name <b>*</b></span><input class="fin" data-kcs-pe="name" value="${esc(e.name)}"></label><label class="fld wide"><span class="flab">Purpose <b>*</b></span><textarea class="fin" rows="2" data-kcs-pe="purpose">${esc(e.purpose)}</textarea></label>
 <label class="fld"><span class="flab">Owner</span><select class="fin" data-kcs-pe="owner">${PEOPLE.map(x=>`<option ${x[0]===e.owner?"selected":""}>${x[0]}</option>`).join("")}</select></label><label class="fld"><span class="flab">Model</span><select class="fin" data-kcs-pe="model">${models.map(x=>`<option ${x===e.model?"selected":""}>${x}</option>`).join("")}</select></label>
 <div class="fld wide"><span class="flab">Risk tier</span><div class="fchips">${["Low","Medium","High"].map(r=>`<button type="button" class="chip" data-kcs-pechip="risk:${r}" aria-pressed="${e.risk===r}">${r}</button>`).join("")}</div><small class="fhelp">Low needs the owner. Medium adds the AI governance lead. High adds Security and Legal and a passing regression gate.</small></div>
 <label class="fld wide"><span class="flab">Prompt text <b>*</b></span><textarea class="fin kcs-code" rows="12" data-kcs-pe="text" spellcheck="false">${esc(e.text)}</textarea><small class="fhelp">Put variables in double braces, for example {{question}}.</small></label>
 <label class="fld wide"><span class="flab">Change note <b>*</b></span><input class="fin" data-kcs-pe="note" value="${esc(e.note)}" placeholder="What changed and why"></label></div>
 <div class="row" style="margin-top:12px"><button class="btn primary" data-kcs-psave>${p?"Save as new version":"Create prompt"}</button><button class="btn" data-kcs-pnew>New blank prompt</button></div></section>
 <section class="card glass kcs-stick"><div class="cardhead"><div><h3>Live test</h3><span class="muted small">Fill the variables and run against the model.</span></div></div><div id="kcs-pvars">${pVarsHTML()}</div><div class="row" style="margin:10px 0"><button class="btn primary" data-kcs-prun>Run test</button><button class="btn quiet" data-kcs-presample>Reset to sample inputs</button></div><div id="kcs-pout">${pOutHTML()}</div></section></div>`}
function pLib(){return `<div class="tablewrap"><table class="kcs-wide"><thead><tr><th>Prompt</th><th>Status</th><th>Risk</th><th>Version</th><th>Model</th><th>Owner</th><th>Variables</th><th>Used by</th></tr></thead><tbody>${PR.map(p=>`<tr data-kcs-pdet="${p.id}" tabindex="0"><td><b>${esc(p.name)}</b><span class="sub">${p.id} · ${esc(p.purpose.slice(0,70))}${p.purpose.length>70?"...":""}</span></td><td>${stP(p.status)}</td><td>${rkP(p.risk)}</td><td><b class="num">${p.prodV||"none"}</b>${p.candV?` <span class="pill info">${p.candV} candidate</span>`:""}</td><td>${esc(p.model)}</td><td>${esc(p.owner)}</td><td>${Object.keys(p.vars).length}</td><td>${p.usedBy.length?esc(p.usedBy.slice(0,2).join(", "))+(p.usedBy.length>2?" +"+(p.usedBy.length-2):""):"nothing"}</td></tr>`).join("")}</tbody></table></div>`}
function pVers(){const p=cur(),[i,j]=K.pvd,va=p.vers[i]||p.vers[0],vb=p.vers[j]||p.vers[p.vers.length-1],d=diff(va.text,vb.text);const vs=n=>p.vers.map((x,k)=>`<option value="${k}" ${k===n?"selected":""}>${x.v} · ${fD(x.d)}</option>`).join("");
 return `<div class="grid g2" style="align-items:start"><section class="card glass"><div class="cardhead"><div><h3>${esc(p.name)}: versions</h3><span class="muted small">Every version is immutable. Only one is in production.</span></div></div><ul class="kcs-vl">${p.vers.slice().reverse().map(x=>`<li><b>${x.v}</b> ${x.v===p.prodV?pill("production","good"):x.v===p.candV?pill("candidate","info"):pill(x.st,"mute")} <span class="muted small">${fD(x.d)} · ${esc(x.by)}</span><div class="small">${esc(x.note)}</div>${x.sc?`<div class="small muted" data-role="metric">pass ${x.sc.pass}% · grounded ${x.sc.ground}% · safe ${x.sc.safe}%</div>`:'<div class="small muted">Not evaluated yet</div>'}</li>`).join("")}</ul></section>
 <section class="card glass"><div class="cardhead"><div><h3>Diff</h3><span class="muted small" data-role="story"><b data-role="metric">+${d.adds}</b> words added, <b data-role="metric">−${d.dels}</b> removed from ${va.v} to ${vb.v}.</span></div></div><div class="row"><label class="kcs-f"><span class="eyebrow">From</span><select class="fin" data-kcs-pvd="0">${vs(i)}</select></label><label class="kcs-f"><span class="eyebrow">To</span><select class="fin" data-kcs-pvd="1">${vs(j)}</select></label></div><div class="kcs-diff kcs-code" style="margin-top:12px">${d.html}</div></section></div>`}
function pAppr(){const p=cur(),ns=need(p),cv=p.candV?vOf(p,p.candV):null,g=p.suite?gateFor(p.suite):null;const gOk=!p.suite?p.risk!=="High":g.ok;
 const steps=[["Draft","candidate saved"],["Eval gate","regression suite passes"],["Approvals",ns.length+" approver"+(ns.length>1?"s":"")],["Production","pointer moves"]];const stage=!p.candV?0:p.status==="In approval"?2:p.status==="Production"&&!p.candV?3:1;
 const allOk=ns.every(n=>p.appr.got.includes(n));
 return `<div class="grid g2" style="align-items:start"><section class="card glass"><div class="cardhead"><div><h3>Approval workflow: ${esc(p.name)}</h3><span class="muted small" data-role="story">${cv?`${esc(p.candV)} is a candidate. ${gOk?"The eval gate passes.":"It cannot go to production because the regression gate fails."}`:"No candidate version. Edit the prompt and save a new version to start an approval."}</span></div>${rkP(p.risk)}</div>
 <ol class="kcs-flow">${steps.map((s,i)=>`<li class="${i<stage?"done":i===stage?"cur":""}"><i>${i<stage?"✓":i+1}</i><b>${s[0]}</b><span class="muted small">${s[1]}</span></li>`).join("")}</ol>
 <div class="eyebrow" style="margin:14px 0 6px">Evidence required</div><ul class="kcs-ckl"><li class="kcs-ck ${gOk?"ok":""}"><i>${gOk?"✓":"•"}</i><span><b>Regression gate</b><small>${p.suite?(g.ok?"Passes: "+g.sum:"Blocked: "+g.sum):p.risk==="High"?"High risk needs a suite. None is attached.":"No suite attached. Allowed for "+p.risk.toLowerCase()+" risk."}</small></span></li><li class="kcs-ck ${cv&&cv.sc?"ok":""}"><i>${cv&&cv.sc?"✓":"•"}</i><span><b>Eval scores recorded</b><small>${cv&&cv.sc?"pass "+cv.sc.pass+"%, grounded "+cv.sc.ground+"%":"Run the suite on the candidate"}</small></span></li></ul>
 ${p.suite&&!g.ok?`<div class="row" style="margin-top:10px"><button class="btn" data-go="kcs_test">Open the regression gate</button></div>`:""}</section>
 <section class="card glass"><div class="cardhead"><div><h3>Approvers</h3><span class="muted small">Required by risk tier. Each approval is audited.</span></div></div><div class="kcs-list">${ns.map(n=>{const got=p.appr.got.includes(n);return `<div class="kcs-li"><div><b>${n}</b><span class="muted small">${got?"Approved":"Waiting"}</span></div>${got?`<span class="pill good">Approved</span>`:`<button class="btn" data-kcs-papp="${esc(n)}" ${p.candV?"":"disabled"}>Record approval</button>`}</div>`}).join("")}</div>
 <div class="row" style="margin-top:14px"><button class="btn" data-kcs-psubmit ${p.candV&&p.status!=="In approval"?"":"disabled"}>Submit for approval</button><button class="btn primary" data-kcs-ppromote ${p.candV&&allOk&&gOk&&p.status==="In approval"?"":"disabled"}>Promote to production</button></div>
 <p class="muted small" style="margin-top:8px">Promotion is blocked until the gate passes and every approver has signed. A failed gate cannot be overridden here; fix the prompt or the case.</p></section></div>`}
function pAB(){const p=cur(),rows=p.vers.filter(x=>x.sc);const best=rows.slice().sort((a,b)=>comp2(b.sc)-comp2(a.sc))[0];const mx=k=>Math.max(...rows.map(r=>r.sc[k]),1);
 return `<section class="card glass"><div class="cardhead"><div><h3>A/B comparison across versions: ${esc(p.name)}</h3><span class="muted small" data-role="story">${best?`Highest composite is <b>${best.v}</b> at ${comp2(best.sc)}. ${best.v!==p.prodV&&p.prodV?`Production is ${p.prodV} at ${comp2(vOf(p,p.prodV).sc)}.`:"It is also the production version."}`:"No version has eval scores yet."}</span></div></div>
 <div class="formula" style="margin-bottom:12px;font-size:15px">Composite = 0.5 × Pass rate + 0.3 × Groundedness + 0.2 × Safety · same golden set for every version · ties go to the cheaper version</div>
 ${rows.length?`<div class="tablewrap"><table class="kcs-wide"><thead><tr><th>Version</th><th>Status</th><th>Pass rate</th><th>Grounded</th><th>Safety</th><th>Composite</th><th>Cost per 1k calls</th><th>p50 latency</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b class="num">${r.v}</b><span class="sub">${esc(r.note)}</span></td><td>${r.v===p.prodV?pill("production","good"):r.v===p.candV?pill("candidate","info"):pill(r.st,"mute")}${best===r&&rows.length>1?" "+pill("best","metric"):""}</td>${["pass","ground","safe"].map(k=>`<td data-role="metric">${qBar(r.sc[k],60)} <b class="num">${r.sc[k]}%</b></td>`).join("")}<td><b class="num" data-role="metric">${comp2(r.sc)}</b></td><td data-role="metric">$${r.sc.cost.toFixed(2)}</td><td data-role="metric">${(r.sc.lat/1000).toFixed(2)} s</td></tr>`).join("")}</tbody></table></div>`:empty("No evaluations","Run a suite on a version to compare it.")}
 <div class="row" style="margin-top:12px">${p.suite?`<button class="btn" data-go="kcs_test">Open the suite</button>`:""}<span class="muted small">Cheaper is not better if safety drops. A version below 100% safety on a High risk prompt is blocked by the gate.</span></div></section>`}
REG("kcs_prompt","Prompt library","ai","M4 5h16v10H8l-4 4zM8 9h8M8 12h5",()=>{if(!K.ped)pLoad(K.pSel);const p=cur(),prod=PR.filter(x=>x.status==="Production").length,ap=PR.filter(x=>x.status==="In approval").length;
 return `<div class="screen kfast">${hero("Prompt library · governed prompts","Every prompt has an owner, a version and a test",`<b>${PR.length} prompts</b> are governed here, <b>${prod}</b> in production and <b>${ap}</b> waiting on approval. The cost-cutting rewrite of the knowledge answer prompt (v4) fails its regression suite, so it cannot reach production.`,`<div class="row"><label class="kcs-f"><span class="eyebrow">Selected prompt</span><select class="fin" data-kcs-psel>${PR.map(x=>`<option value="${x.id}" ${x.id===p.id?"selected":""}>${x.id} · ${esc(x.name)}</option>`).join("")}</select></label>${fchip("m_ground")}${fchip("m_judge")}${whyPop("Prompts are code. They change what the AI does, so each change is versioned, evaluated and approved by risk tier.")}</div>`)}${lensNote()}
 ${tiles([TL("In production",prod,"prompts live now","good"),TL("Awaiting approval",ap,"cannot ship until approved",ap?"warn":"good"),TL("High risk",PR.filter(x=>x.risk==="High"&&x.status!=="Retired").length,"need Security and Legal","warn"),TL("Average pass rate",Math.round(PR.filter(x=>x.status==="Production").reduce((n,x)=>n+vOf(x,x.prodV).sc.pass,0)/prod)+"%","production versions","info")])}
 ${views("kcs_pt",["Library","Versions and diff","Editor and test","Approval","A/B compare"],[pLib(),pVers(),pEditor(),pAppr(),pAB()])}</div>`});

