/* ---------- extraction: article > structured procedure ---------- */
const KW=[[/look ?up|registered|check the (user|client)|read the .* status|directory/i,"entra.getUser"],[/reset.*(mfa|multifactor|method)/i,"entra.resetMfa"],[/revoke|sign.?out|sessions/i,"entra.revokeSessions"],[/guest|vendor access|add .* group/i,"entra.grantGuest"],[/read-only|read only mode/i,"portal.setMode"],[/traffic|weight|secondary region/i,"traffic.shiftWeight"],[/promote|replica/i,"db.promoteReplica"],[/clear.*cache|cache/i,"search.clearCache"],[/rebuild.*index|full rebuild/i,"search.rebuildIndex"],[/smoke|verify|confirm .* (works|healthy)/i,"smoke.run"],[/status (update|page)|post .*status/i,"itsm.postStatus"],[/notify|message|email|tell the|page the/i,"teams.notify"],[/share|link/i,"m365.shareLink"],[/split/i,"cr.splitUpload"],[/vpn profile|vpn client/i,"vpn.reissueProfile"],[/export|report/i,"erp.exportLease"]];
const guardFor=t=>{const r=t?t[4]:"Low",k=t?t[3]:"read";return k==="read"?"Read only":(r==="High"||k==="admin")?"Needs approval":r==="Medium"?"Rate limited":"Notify the owner"};
function extract(k){const a=k.art?byId(k.id):null;let lines=[];if(a&&a.s&&a.s.res)lines=a.s.res.split("\n").map(x=>x.replace(/^\s*\d+\.\s*/,"").trim()).filter(Boolean);
 if(!lines.length){const sx={Runbook:["Confirm the trigger and the target","Prepare a rollback point","Apply the documented change","Run a smoke test to verify","Post a note and close"],SOP:["Check the request is complete","Look up the requester in the directory","Apply the approved change","Notify the requester and close"],"Resolved-ticket pattern":["Look up the affected user or device","Apply the documented fix","Verify the fix worked","Notify the user and link the ticket"],"Codified process":["Receive the trigger","Check the preconditions","Run the standard sequence","Verify and record the outcome"]};lines=(sx[k.type]||["Check the request","Apply the documented fix","Verify the outcome","Notify the requester and close"]).slice()}
 const steps=lines.slice(0,8).map(l=>{const m=KW.find(x=>x[0].test(l));const tid=m?m[1]:"itsm.updateIncident",t=toolOf(tid);return {n:l.replace(/\.$/,""),tool:tid,guard:guardFor(t)}});
 const txt=(k.t+" "+lines.join(" ")).toLowerCase();const inputs=[["ticket","incident",1]];if(/user|editor|person|reset|laptop/.test(txt))inputs.unshift(["user","person",1]);if(/vendor/.test(txt))inputs.push(["vendor user","person",1]);if(/date|expiry|quarter/.test(txt))inputs.push(["end date","date",1]);
 const hi=steps.some(s=>s.guard==="Needs approval");const guards=["Run inside the incident or request it came from"].concat(hi?["Dry run in test first","Rollback ready before any write"]:[]).concat(k.sens==="Restricted"||k.sens==="Confidential"?["Never log secrets or personal data"]:[]);
 return {steps,inputs,guards,ai:{conf:Math.min(.95,k.conf/100*.92),n:lines.length}}}
const riskOf=steps=>steps.reduce((m,s)=>{const t=toolOf(s.tool);const r=t?t[4]:"Low";return r==="High"?"High":r==="Medium"&&m!=="High"?"Medium":m},"Low");
