const STOPW=new Set("what does the a an article item runbook doc document link links linked to of for about how which is are do with me show tell and".split(" "));
function findItem(q){const tk=q.toLowerCase().replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(w=>w.length>1&&!STOPW.has(w));if(!tk.length)return null;let best=null,bs=0;items().forEach(k=>{const s=(k.t+" "+k.id+" "+k.svcN).toLowerCase();let sc=0;tk.forEach(w=>{if(s.includes(w))sc+=2});if(!k.gen)sc+=.5;if(sc>bs){bs=sc;best=k}});return bs>=2?best:null}
ASKX.push(q=>{const l=q.toLowerCase();
 if(/(which|what|any).*(articles?|items?|runbooks?|knowledge|sops?).*(can be|could be|ready to|to) ?(automat)|ready to automate|automation candidates/.test(l)){const c=items().filter(k=>KT[k.type].proc>=.8&&k.st==="Published").sort((a,b)=>b.ready-a.ready).slice(0,5);S.v.kcs_hv=1;go("kcs_home");say(q,{t:"<b>"+items().filter(k=>k.band===BANDS[0]).length+" items are ready to automate</b> (readiness 80 or more) and "+items().filter(k=>k.band===BANDS[1]).length+" are close. Best five: "+c.map(k=>"<b>"+esc(k.id)+"</b> "+esc(k.t)+" ("+k.ready+(k.skill?", already skill "+k.skill:"")+")").join("; ")+". Readiness = 0.30 × determinism + 0.25 × completeness + 0.20 × tests + 0.25 × safety. I opened the Library; filter by Automation readiness to see them all.",steps:["Scored every procedural item","Ranked by readiness","Opened the Knowledge library"]});return true}
 if(/(what|which).*(does|do).*(link|connect)|links? to|linked to|what is .* linked/.test(l)&&/article|item|runbook|doc|vpn|failover|mfa|retention|lease|kb\d|sop|rb-/.test(l)){const k=findItem(q);if(k){const g=relRows(k);say(q,{t:"<b>"+esc(k.id)+" "+esc(k.t)+"</b> links to "+g.map(x=>x.rows.length+" "+x.label.toLowerCase()).join(", ")+". Owner "+esc(k.own)+", confidence "+k.conf+"%, readiness "+k.ready+". I opened its drawer with every linked record.",steps:["Matched the item by title","Read its relationships","Opened the item"]});openItem(k.id);return true}}
 if(/agent skills?|skill success|how many skills|skills? (are|is) (active|running|awaiting)|which skills/.test(l)){go("kcs_skills");const sk=allSkills();say(q,{t:"<b>"+sk.filter(s=>s.status==="Active").length+" agent skills are active</b> out of "+sk.length+". Success rate "+METRICS.m_skill_ok.cur+"%, "+sk.reduce((a,s)=>a+s.esc,0)+" escalations, "+sk.filter(s=>s.status==="Awaiting approval").length+" awaiting approval. I opened the dashboard.",steps:["Counted skills by status","Computed success from runs","Opened Agent skills"]});return true}
 let m=l.match(/promote (.+?) (?:to|into) (?:a |an )?(?:agent )?skill/);if(m){const k=findItem(m[1]);if(k){promoteForm(k.id);say(q,{t:"Opened the promote form for <b>"+esc(k.id)+" "+esc(k.t)+"</b> (readiness "+k.ready+"). AI will extract the steps and you will edit tools and guardrails before it goes for approval.",steps:["Matched the item","Opened the promote form"]});return true}}
 if(/(new|create|add) (a )?(knowledge item|runbook|sop|policy|decision record|architecture doc)/.test(l)){newItemForm();say(q,{t:"Opened the new knowledge item form. It asks for the source, owner and confidence so the item can be trusted.",steps:["Opened the form"]});return true}
 m=l.match(/(?:path|route|connection) (?:from|between) (.+?) (?:to|and) (.+)/);if(m){S.kgx=S.kgx||{};S.kgx.cmd={path:[m[1].trim(),m[2].trim()]};go("vault");say(q,{t:"Opening the knowledge graph and finding the shortest path between <b>"+esc(m[1])+"</b> and <b>"+esc(m[2])+"</b>.",steps:["Matched both ends","Searched the graph","Highlighted the path"]});return true}
 m=l.match(/(?:dot.?walk|walk|impact sources?|what depends on|what would be affected by|impact of) (?:from |of |on )?(.+)/);if(m&&/graph|walk|impact|depends|affected/.test(l)){S.kgx=S.kgx||{};S.kgx.cmd={walk:m[1].trim()};go("vault");say(q,{t:"Opening the knowledge graph and dot-walking from <b>"+esc(m[1])+"</b>. The path and counts per step appear in the side panel.",steps:["Matched the start node","Walked the relationships","Showed counts and paths"]});return true}
 if(/knowledge (lifecycle|loop)|source.*output|kcs loop/.test(l)){S.v.kcs_hv=0;go("kcs_home");say(q,{t:"The loop is capture, structure, reuse, improve, automate. Right now "+items().filter(k=>k.st==="Draft").length+" drafts, "+items().filter(k=>k.st==="In review").length+" in review, "+seedImp().filter(i=>i.st!=="Fixed and reused").length+" open improvement tasks and "+allSkills().filter(s=>s.status==="Active").length+" active skills.",steps:["Counted each stage","Opened the lifecycle"]});return true}
 return false});
